SELECT molecule_dictionary.chembl_id, molecule_dictionary.pref_name, drug_indication.mesh_id, drug_indication.mesh_heading, drug_indication.efo_id AS indication_curie, drug_indication.efo_term AS indication_label, drug_indication.max_phase_for_ind FROM molecule_dictionary INNER JOIN drug_indication ON molecule_dictionary.molregno = drug_indication.molregno WHERE molecule_dictionary.max_phase = 4 AND drug_indication.max_phase_for_ind = 4 ORDER BY molecule_dictionary.chembl_id ASC, molecule_dictionary.pref_name ASC, drug_indication.mesh_id ASC, drug_indication.mesh_heading ASC, indication_curie ASC, indication_label ASC, drug_indication.max_phase_for_ind ASC
